CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE agent_state AS ENUM ('queued','leased','running','waiting_approval','blocked','succeeded','failed','cancelled','stale'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE extractor_type AS ENUM ('deterministic','model','human'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE fact_status AS ENUM ('candidate','accepted','conflicted','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((id = owner_organization_id) OR id <> owner_organization_id), CONSTRAINT organizations_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY; ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY organizations_tenant ON organizations USING (owner_organization_id = NULLIF(current_setting('app.owner_organization_id', true),'')::uuid);
CREATE TABLE IF NOT EXISTS organization_aliases (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), alias text NOT NULL, normalized_alias text NOT NULL);
CREATE TABLE IF NOT EXISTS legal_entities (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), legal_name text NOT NULL, jurisdiction text, registration_id text);
CREATE TABLE IF NOT EXISTS sources (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, uri text NOT NULL, retrieved_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS facts (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, subject_type text NOT NULL, subject_id uuid NOT NULL, predicate text NOT NULL, value jsonb NOT NULL, source_id uuid REFERENCES sources(id), confidence numeric CHECK (confidence BETWEEN 0 AND 1), observed_at timestamptz NOT NULL, extractor extractor_type NOT NULL, status fact_status NOT NULL DEFAULT 'candidate');
CREATE TABLE IF NOT EXISTS people (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, organization_id uuid REFERENCES organizations(id), name text NOT NULL);
CREATE TABLE IF NOT EXISTS person_roles (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, person_id uuid NOT NULL REFERENCES people(id), organization_id uuid NOT NULL REFERENCES organizations(id), role text NOT NULL);
CREATE TABLE IF NOT EXISTS contact_channels (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, person_id uuid REFERENCES people(id), channel_type text NOT NULL, address text NOT NULL, consent_status text NOT NULL, do_not_contact boolean NOT NULL DEFAULT false, outreach_allowed boolean NOT NULL DEFAULT false, permission_reason text, CHECK (NOT outreach_allowed OR (NOT do_not_contact AND permission_reason IS NOT NULL)));
CREATE TABLE IF NOT EXISTS web_properties (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, organization_id uuid NOT NULL REFERENCES organizations(id), domain text NOT NULL, verified_at timestamptz);
CREATE TABLE IF NOT EXISTS event_counters (owner_organization_id uuid PRIMARY KEY, next_sequence bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS domain_events (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, sequence bigint NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, event_type text NOT NULL, event_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), actor text, trace_id text, causation_id uuid, correlation_id uuid, idempotency_key text, UNIQUE(owner_organization_id, sequence), UNIQUE(owner_organization_id, idempotency_key));
CREATE TABLE IF NOT EXISTS agent_runs (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, state agent_state NOT NULL DEFAULT 'queued', lease_owner text, lease_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS run_steps (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, run_id uuid NOT NULL REFERENCES agent_runs(id), sequence integer NOT NULL, attempt integer NOT NULL DEFAULT 1, state text NOT NULL, checkpoint jsonb, input_projection jsonb, output_projection jsonb, error_provenance jsonb, lease_owner text, lease_expires_at timestamptz, started_at timestamptz, finished_at timestamptz, UNIQUE(run_id, sequence));
CREATE TABLE IF NOT EXISTS evaluation_requests (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, idempotency_key text NOT NULL, status text NOT NULL, UNIQUE(owner_organization_id, idempotency_key));
CREATE TABLE IF NOT EXISTS evaluation_references (id uuid PRIMARY KEY DEFAULT uuidv7(), owner_organization_id uuid NOT NULL, request_id uuid REFERENCES evaluation_requests(id), run_id text NOT NULL, recipe text NOT NULL, execution_status text NOT NULL, assessment_status text NOT NULL, policy_verdict text, artifact_uri text NOT NULL, result_sha256 text NOT NULL, subject_context_sha256 text NOT NULL, projection jsonb, cost_total numeric, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS domain_events_owner_seq ON domain_events(owner_organization_id, sequence); CREATE INDEX IF NOT EXISTS agent_runs_lease ON agent_runs(owner_organization_id, state, lease_expires_at); CREATE INDEX IF NOT EXISTS evaluation_requests_idem ON evaluation_requests(owner_organization_id, idempotency_key);
ALTER TABLE organization_aliases ADD CONSTRAINT organization_aliases_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE legal_entities ADD CONSTRAINT legal_entities_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE sources ADD CONSTRAINT sources_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE facts ADD CONSTRAINT facts_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE people ADD CONSTRAINT people_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE person_roles ADD CONSTRAINT person_roles_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE contact_channels ADD CONSTRAINT contact_channels_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE web_properties ADD CONSTRAINT web_properties_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE domain_events ADD CONSTRAINT domain_events_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE agent_runs ADD CONSTRAINT agent_runs_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE run_steps ADD CONSTRAINT run_steps_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE evaluation_requests ADD CONSTRAINT evaluation_requests_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
ALTER TABLE evaluation_references ADD CONSTRAINT evaluation_references_owner_fk FOREIGN KEY (owner_organization_id) REFERENCES organizations(id) NOT VALID;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['organization_aliases','legal_entities','sources','facts','people','person_roles','contact_channels','web_properties','event_counters','domain_events','agent_runs','run_steps','evaluation_requests','evaluation_references'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY %I_tenant ON %I USING (owner_organization_id = NULLIF(current_setting(''app.owner_organization_id'', true),'''')::uuid)', t, t); END LOOP; END $$;
